{"code": "import math

def count_trailing_zeroes(n):
    factorial = math.factorial(n)
    s = str(factorial)
    count = 0
    for char in reversed(s):
        if char == '0':
            count += 1
        else:
            break
    return count

print(count_trailing_zeroes(42))"}

